CREATE TABLE coop_rooms (code TEXT PRIMARY KEY NOT NULL, host_token TEXT NOT NULL, guest_token TEXT, host_role INTEGER NOT NULL, guest_role INTEGER, host_health INTEGER NOT NULL DEFAULT 0, guest_health INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'waiting', seed INTEGER NOT NULL, snapshot TEXT, guest_input TEXT, host_seq INTEGER NOT NULL DEFAULT 0, guest_seq INTEGER NOT NULL DEFAULT 0, host_seen INTEGER NOT NULL, guest_seen INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL);
